extra='''    public static function catalog_facets(WP_REST_Request $r){$ok=self::require_wc();if(is_wp_error($ok))return $ok;$category=absint($r->get_param('category'));$tax=[];if($category)$tax[]=['taxonomy'=>'product_cat','field'=>'term_id','terms'=>[$category],'include_children'=>true];$args=['post_type'=>'product','post_status'=>'publish','posts_per_page'=>-1,'fields'=>'ids','no_found_rows'=>true];if($tax)$args['tax_query']=$tax;$ids=(new WP_Query($args))->posts;$brands=[];$models=[];$min=null;$max=null;foreach($ids as $id){$p=wc_get_product($id);if(!$p||!$p->is_visible())continue;$pr=(float)$p->get_price();if($pr>0){$min=$min===null?$pr:min($min,$pr);$max=$max===null?$pr:max($max,$pr);}foreach(['product_brands','product_brand','pa_brand','brand'] as $bt){if(!taxonomy_exists($bt))continue;$ts=wp_get_post_terms($id,$bt);if(!is_wp_error($ts))foreach($ts as $t)$brands[$t->term_id]=['id'=>(int)$t->term_id,'name'=>$t->name,'slug'=>$t->slug];if($ts&&!is_wp_error($ts))break;}if(taxonomy_exists('product_tag')){$ts=wp_get_post_terms($id,'product_tag');if(!is_wp_error($ts))foreach($ts as $t)$models[$t->term_id]=['id'=>(int)$t->term_id,'name'=>$t->name,'slug'=>$t->slug];}}uasort($brands,fn($a,$b)=>strcasecmp($a['name'],$b['name']));uasort($models,fn($a,$b)=>strcasecmp($a['name'],$b['name']));return rest_ensure_response(['price'=>['min'=>$min?:0,'max'=>$max?:0],'brands'=>array_values($brands),'models'=>array_values($models),'subcategories'=>$category?self::category_rows($category):self::category_rows(0)]);}\n\n    public static function rfq(WP_REST_Request $r){$b=$r->get_json_params();if(!is_array($b))$b=[];$email=sanitize_email((string)($b['email']??''));$name=sanitize_text_field((string)($b['name']??''));if(!$name||!is_email($email))return new WP_Error('autoid_rfq_invalid','Numele și emailul sunt obligatorii.',['status'=>400]);$products=[];foreach((array)($b['products']??[]) as $row){$id=absint($row['id']??0);$qty=max(1,absint($row['qty']??1));$p=$id?wc_get_product($id):null;if($p)$products[]=$qty.' x '.$p->get_name().' ('.$p->get_sku().')';}if(!$products)return new WP_Error('autoid_rfq_empty','Adaugă cel puțin un produs în cererea de ofertă.',['status'=>400]);$company=sanitize_text_field((string)($b['company']??''));$phone=sanitize_text_field((string)($b['phone']??''));$message=sanitize_textarea_field((string)($b['message']??''));$to=(string)apply_filters('autoid_mobile_rfq_email',get_option('admin_email'));$body="Nume: $name\\nEmail: $email\\nCompanie: $company\\nTelefon: $phone\\n\\nProduse:\\n- ".implode("\\n- ",$products)."\\n\\nMesaj:\\n$message";$sent=wp_mail($to,'Cerere ofertă din aplicația AutoID',$body,['Reply-To: '.$name.' <'.$email.'>']);if(!$sent)return new WP_Error('autoid_rfq_mail','Cererea nu a putut fi trimisă.',['status'=>500]);return rest_ensure_response(['sent'=>true]);}\n\n    public static function consultation_request(WP_REST_Request $r){$b=$r->get_json_params();if(!is_array($b))$b=[];$email=sanitize_email((string)($b['email']??''));$name=sanitize_text_field((string)($b['name']??''));$message=sanitize_textarea_field((string)($b['message']??''));if(!$name||!is_email($email)||!$message)return new WP_Error('autoid_consult_invalid','Numele, emailul și mesajul sunt obligatorii.',['status'=>400]);$to=(string)apply_filters('autoid_mobile_consultation_email',get_option('admin_email'));$body="Nume: $name\\nEmail: $email\\nTelefon: ".sanitize_text_field((string)($b['phone']??''))."\\nCompanie: ".sanitize_text_field((string)($b['company']??''))."\\n\\n$message";$sent=wp_mail($to,'Solicitare consultanță tehnică din aplicația AutoID',$body,['Reply-To: '.$name.' <'.$email.'>']);if(!$sent)return new WP_Error('autoid_consult_mail','Solicitarea nu a putut fi trimisă.',['status'=>500]);return rest_ensure_response(['sent'=>true]);}\n\n'''
